content.query:
let views = pageViews | where timestamp {TimeRange};
let events = customEvents | where timestamp {TimeRange};
let failures = exceptions | where timestamp {TimeRange};
union
  (views | summarize Value=dcount(user_Id) | extend Metric='Active users'),
  (views | summarize Value=dcount(session_Id) | extend Metric='Sessions'),
  (views | summarize Value=count() | extend Metric='Screen views'),
  (events | summarize Value=count() | extend Metric='Feature events'),
  (failures | summarize Value=count() | extend Metric='Exceptions')
| project Metric, Value
